const data = $input.first().json;

function trend(current, previous) {
  if (!previous || previous === 0) return current > 0 ? '+∞' : '-';  const pct = ((current - previous) / previous * 100).toFixed(1);
  const sign = pct > 0 ? '+' : '';
  return `${sign}${pct}%`;
}

const issuesFixed = Number(data.issues_fixed) || 0;
const issuesFailed = Number(data.issues_failed) || 0;
const tokensUsed = Number(data.tokens_consumed) || 0;
const activeTenants = Number(data.active_tenants) || 0;
const newSignups = Number(data.new_signups) || 0;
const revenueCents = Number(data.total_revenue_cents) || 0;
const totalAccounts = Number(data.total_accounts) || 0;

const prevFixed = Number(data.prev_issues_fixed) || 0;
const prevTokens = Number(data.prev_tokens) || 0;
const prevTenants = Number(data.prev_active_tenants) || 0;
const prevSignups = Number(data.prev_signups) || 0;
const prevRevenue = Number(data.prev_revenue_cents) || 0;

const totalRuns = issuesFixed + issuesFailed;
const fixRate = totalRuns > 0 ? (issuesFixed / totalRuns * 100).toFixed(1) : 'N/A';

const revenue = '$' + (revenueCents / 100).toFixed(2);
const tokensDisplay = tokensUsed >= 1000000
  ? (tokensUsed / 1000000).toFixed(1) + 'M'
  : tokensUsed >= 1000
    ? (tokensUsed / 1000).toFixed(1) + 'K'
    : String(tokensUsed);

const timeframe = 'Mon, ' + new Date(Date.now() - 7 * 86400000).toLocaleDateString('en-US', { month: 'short', day: 'numeric' }) + ' — ' + new Date().toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });

const blocks = [
  {
    type: 'header',
    text: { type: 'plain_text', text: ':bar_chart: Weekly Usage Report' }
  },
  {
    type: 'context',
    elements: [
      { type: 'mrkdwn', text: timeframe }
    ]
  },
  { type: 'divider' },
  {
    type: 'section',
    fields: [
      { type: 'mrkdwn', text: `*Issues Fixed:*\n${issuesFixed} (${trend(issuesFixed, prevFixed)})` },
      { type: 'mrkdwn', text: `*Fix Rate:*\n${fixRate}%` }
    ]
  },
  {
    type: 'section',
    fields: [
      { type: 'mrkdwn', text: `*Tokens Consumed:*\n${tokensDisplay} (${trend(tokensUsed, prevTokens)})` },
      { type: 'mrkdwn', text: `*Active Tenants:*\n${activeTenants} (${trend(activeTenants, prevTenants)})` }
    ]
  },
  {
    type: 'section',
    fields: [
      { type: 'mrkdwn', text: `*New Signups:*\n${newSignups} (${trend(newSignups, prevSignups)})` },
      { type: 'mrkdwn', text: `*Total Accounts:*\n${totalAccounts}` }
    ]
  },
  {
    type: 'section',
    fields: [
      { type: 'mrkdwn', text: `*Revenue (7d):*\n${revenue} (${trend(revenueCents, prevRevenue)})` }
    ]
  },
  { type: 'divider' },
  {
    type: 'context',
    elements: [
      { type: 'mrkdwn', text: ':chart_with_upwards_trend: _Trends compare this week vs previous week_' }
    ]
  }
];

return [{
  json: {
    channel: '#syntaro-metrics',
    attachments: JSON.stringify([{
      color: '#3498DB',
      blocks: blocks
    }])
  }
}];
